package co.golink.tester.ui.i18n

/**
 * Textos do Pass: cópia de `pass2.*` dos JSON da web (resources/js/i18n/lang).
 * GERADO por ops/i18n/gen_i18n_pass.py (repo web) — não editar à mão; mudar o JSON e voltar a gerar.
 * Ao contrário do resto da app, a chave é a da web (não a frase PT): os textos têm
 * parâmetros `{n}` e mudam em conjunto com a web.
 */
object I18nPass {
    /** Texto na língua atual (lê [I18n.lang]: recompõe ao mudar). */
    fun t(key: String, vararg params: Pair<String, Any?>): String {
        val row = rows[key] ?: return key
        var text = row[when (I18n.lang) { I18n.EN -> 1; I18n.FR -> 2; I18n.ES -> 3; else -> 0 }]
        for ((name, value) in params) text = text.replace("{$name}", value?.toString().orEmpty())
        return text
    }

    fun has(key: String): Boolean = key in rows

